429	/**
430	 * Rebuilds one slot from its saved snapshot: drops unknown ids, clamps the
431	 * count, and clamps/defaults durability for gear (a non-positive saved
432	 * durability means the piece broke and is dropped). Returns an empty slot for
433	 * anything invalid. Shared by inventory and container restore.
434	 */
435	function restoreSlot(saved: SavedSlot | undefined): InventorySlot {
436	  if (!saved?.id || saved.count <= 0 || !ITEM_DEF_BY_ID[saved.id]) return createEmptySlot();
437	  const slot = createSlot(saved.id, Math.min(maxStackSizeForItem(saved.id), Math.max(0, Math.floor(saved.count))));
438	  if ((slot.kind === "tool" || slot.kind === "weapon" || slot.kind === "armor") && slot.maxDurability) {
439	    if (typeof saved.durability === "number") {
440	      const loaded = Math.floor(saved.durability);
441	      if (loaded <= 0) return createEmptySlot();
442	      slot.durability = Math.max(1, Math.min(slot.maxDurability, loaded));
443	    } else {
444	      slot.durability = slot.maxDurability;
445	    }
446	    // Enchantments live only on durable gear; validated against the known set.
447	    const enchantments = restoreEnchantments(saved.enchantments);
448	    if (enchantments) slot.enchantments = enchantments;
449	    // A custom name (anvil rename) also lives only on durable gear; trim and cap it.
450	    if (typeof saved.customName === "string") {
451	      const name = saved.customName.trim().slice(0, CUSTOM_NAME_MAX_LEN);
452	      if (name) slot.customName = name;
453	    }
454	  }
455	  return slot;
456	}
