579	/**
580	 * Reads persisted mobs from a save into validated SavedMob entries — dropping
581	 * unknown kinds, non-finite coords, non-positive/garbage hp, and unknown factions.
582	 * The engine rebuilds the live MobState from these (re-grounding y onto current
583	 * terrain, assigning fresh ids), so this stays pure data — no THREE / no rng.
584	 */
585	export function restoreMobs(save: SaveData): SavedMob[] {
586	  if (!Array.isArray(save.mobs)) return [];
587	  const out: SavedMob[] = [];
588	  for (const entry of save.mobs) {
589	    if (!entry || typeof entry.kind !== "string" || !MOB_TEMPLATES[entry.kind]) continue;
590	    if (!Number.isFinite(entry.x) || !Number.isFinite(entry.y) || !Number.isFinite(entry.z)) continue;
591	    if (!Number.isFinite(entry.hp) || entry.hp <= 0) continue;
592	    if (typeof entry.faction !== "string" || !Object.hasOwn(VALID_MOB_FACTIONS, entry.faction)) continue;
593	    // Only the two persistent shapes are accepted (mirrors isPersistentMob), so a
594	    // stale/edited save can't resurrect e.g. a "pet zombie": an owned ally pet, or
595	    // an owner-less villager resident. Anything else is dropped.
596	    const isPet = typeof entry.owner === "string" && entry.owner.length > 0 && entry.faction === "ally";
597	    const isResident = entry.owner == null && entry.faction === "villager";
598	    if (!isPet && !isResident) continue;
599	    const saved: SavedMob = { kind: entry.kind, x: entry.x, y: entry.y, z: entry.z, hp: entry.hp, faction: entry.faction };
600	    if (typeof entry.owner === "string" && entry.owner.length > 0) saved.owner = entry.owner;
601	    if (entry.sitting === true) saved.sitting = true;
602	    if (Number.isFinite(entry.ageTimer) && (entry.ageTimer ?? 0) > 0) saved.ageTimer = entry.ageTimer;
603	    if (isProfession(entry.profession)) saved.profession = entry.profession;
604	    out.push(saved);
605	  }
606	  return out;
607	}
608	
609	/**
610	 * Reads chest containers from a save into validated, CHEST_SLOTS-length slot
611	 * arrays keyed by voxel index. Per-slot validation only — the engine still
612	 * confirms each index actually holds a Chest block before using it.
613	 */
614	export function readContainers(save: SaveData): Array<{ index: number; slots: InventorySlot[] }> {
615	  if (!Array.isArray(save.blockEntities)) return [];
616	  const out: Array<{ index: number; slots: InventorySlot[] }> = [];
617	  for (const entry of save.blockEntities) {
618	    if (!entry || !Number.isFinite(entry.index) || !Array.isArray(entry.slots)) continue;
619	    const slots = Array.from({ length: CHEST_SLOTS }, (_, i) => restoreSlot(entry.slots[i]));
620	    out.push({ index: entry.index, slots });
621	  }
622	  return out;
623	}
624	
625	/**
626	 * Rebuilds inventory slots from a save, dropping unknown items, clamping
627	 * counts and durability, and skipping broken gear. Supports both the current
628	 * inventorySlots shape and the legacy inventoryCounts shape. Returns null when
629	 * the save carries no inventory.
630	 */
631	export function restoreInventorySlots(save: SavedPlayer & { inventoryCounts?: Record<string, number> }): InventorySlot[] | null {
632	  if (Array.isArray(save.inventorySlots)) {
633	    const slots = Array.from({ length: INVENTORY_SLOTS }, () => createEmptySlot());
634	    for (let i = 0; i < Math.min(INVENTORY_SLOTS, save.inventorySlots.length); i += 1) {
635	      slots[i] = restoreSlot(save.inventorySlots[i]);
636	    }
637	    return slots;
638	  }
639	
640	  if (save.inventoryCounts) {
641	    const slots = Array.from({ length: INVENTORY_SLOTS }, () => createEmptySlot());
642	    let cursor = 0;
643	    for (const [id, raw] of Object.entries(save.inventoryCounts)) {
644	      if (!ITEM_DEF_BY_ID[id]) continue;
645	      let remaining = Math.max(0, Math.floor(raw));
646	      while (remaining > 0 && cursor < slots.length) {
647	        const add = Math.min(maxStackSizeForItem(id), remaining);
648	        slots[cursor] = createSlot(id, add);
649	        cursor += 1;
650	        remaining -= add;
651	      }
652	    }
653	    return slots;
654	  }
655	
656	  return null;
657	}
658	
659	/** Restores worn armor, rebuilding each piece through restoreSlot and dropping anything that isn't valid armor for its slot. */
660	export function restoreEquippedArmor(save: SavedPlayer): EquippedArmor | null {
661	  if (!save.equippedArmor) return null;
662	  const next = createEmptyArmorEquipment();
663	  for (const armorSlot of ARMOR_SLOTS) {
664	    const saved = save.equippedArmor[armorSlot];
665	    if (!saved) continue;
666	    const slot = restoreSlot(saved);
667	    if (slot.kind !== "armor" || slot.armorSlot !== armorSlot || slot.count <= 0) continue;
668	    next[armorSlot] = slot;
669	  }
670	  return next;
671	}
672	
673	export function restoreSelectedSlot(save: SavedPlayer): number | null {
674	  if (typeof save.selectedSlot !== "number") return null;
675	  return normalizeSelectedSlot(save.selectedSlot);
676	}
677	
678	/** Restores the day clock from a save (finite, non-negative); null if absent/invalid. */
679	export function restoreDayClock(save: SaveData): number | null {
680	  if (typeof save.dayClock !== "number" || !Number.isFinite(save.dayClock) || save.dayClock < 0) return null;
681	  return save.dayClock;
682	}
683	
684	/** Restores hearts clamped to 1..MAX_HEARTS; null if absent/invalid. */
685	export function restoreHearts(save: SavedPlayer): number | null {
686	  if (typeof save.hearts !== "number" || !Number.isFinite(save.hearts)) return null;
687	  return Math.max(1, Math.min(MAX_HEARTS, Math.floor(save.hearts)));
688	}
689	
690	/** Restores hunger clamped to 0..MAX_HUNGER; null if absent/invalid. */
691	export function restoreHungerLevel(save: SavedPlayer): number | null {
692	  if (typeof save.hunger !== "number" || !Number.isFinite(save.hunger)) return null;
693	  return Math.max(0, Math.min(MAX_HUNGER, Math.floor(save.hunger)));
694	}
695	
696	/** Restores banked XP (finite, ≥ 0); 0 when absent or invalid. */
697	export function restoreXp(save: SavedPlayer): number {
698	  if (typeof save.xp !== "number" || !Number.isFinite(save.xp) || save.xp < 0) return 0;
699	  return Math.floor(save.xp);
700	}
701	
702	/** Restores the saved game mode; "survival" when absent or invalid (pre-v8 saves). */
703	export function restoreGameMode(save: SavedPlayer): GameMode {
704	  return isGameMode(save.gameMode) ? save.gameMode : "survival";
705	}
706	
707	/** Restores the saved difficulty; "normal" when absent or invalid (pre-v9 saves). */
708	export function restoreDifficulty(save: SaveData): Difficulty {
709	  return isDifficulty(save.difficulty) ? save.difficulty : "normal";
710	}
711	
712	/** Restores the Hardcore flag; false when absent or non-boolean (pre-v10 saves). */
713	export function restoreHardcore(save: SaveData): boolean {
714	  return save.hardcore === true;
715	}
716	
717	/** Restores the permadeath game-over flag — only ever true on a hardcore save, so a stray flag on a non-hardcore (corrupt) save can't lock it into spectator. */
718	export function restoreGameOver(save: Pick<SaveData, "hardcore">, saved: SavedPlayer): boolean {
719	  return save.hardcore === true && saved.gameOver === true;
720	}
721	
722	/** Restores the bed respawn point; null if absent or explicitly cleared. */
723	export function restoreSpawnPoint(save: SavedPlayer): { x: number; y: number; z: number } | null {
724	  const sp = save.spawnPoint;
725	  if (!sp || !Number.isFinite(sp.x) || !Number.isFinite(sp.y) || !Number.isFinite(sp.z)) return null;
726	  return { x: Math.floor(sp.x), y: Math.floor(sp.y), z: Math.floor(sp.z) };
727	}
728	
729	/**
730	 * Restores the player's position; null when absent or non-finite. A corrupt save
731	 * with NaN/Infinity coords would otherwise load a broken world — and slip past the
732	 * `position.y < 2` unstuck net, since any comparison with NaN is false. Coords stay
733	 * floats (the player isn't grid-aligned), unlike the floored spawn point.
734	 */
735	export function restorePlayerPosition(save: SavedPlayer): { x: number; y: number; z: number } | null {
736	  const p = save.position;
737	  if (!p || !Number.isFinite(p.x) || !Number.isFinite(p.y) || !Number.isFinite(p.z)) return null;
738	  return { x: p.x, y: p.y, z: p.z };
739	}
